# =============================================================================
# TRAV17 / TRAJ31 test panel -- analysis
#
# Reads the 80 folds generated by generate_TRAJ31_test.R and asks whether
# TRAJ31 is a genuinely strong partner for TRAV17, or whether the single 0.818
# step-0 fold was the maximum of 51 noisy draws.
#
# Two arms, TRAV17 fixed, dummy beta, matched on CDR3 length (11-14):
#   TRAJ31  : J = TRAJ31
#   otherJ  : J drawn uniformly from the other TRAV17 cells with a CDR3 baseline
#
# Usage:  Rscript analyze_TRAJ31_test.R
# =============================================================================

SCORE_COL <- "iptm_pair_mean"
RUN_DIR   <- "TCR_motif_atlas_cdr3_templated_new_installation_reduced_cycles_NY-ESO-1"
TEST_DIR  <- file.path(RUN_DIR, "struc_preds_traj31_test")
STEP0_DIR <- file.path(RUN_DIR, "A0201_SLLMWITQC", "step0")

### ---- Load the test panel ---------------------------------------------------

out <- read.csv(file.path(TEST_DIR, "traj31_test", "output.csv"), stringsAsFactors = FALSE)
ann <- read.csv(file.path(TEST_DIR, "traj31_test_annotation.csv"), stringsAsFactors = FALSE)

d <- merge(ann, out[, c("ID", SCORE_COL)], by = "ID")
d$score <- d[[SCORE_COL]]
stopifnot(nrow(d) == nrow(ann))

message(sprintf("test panel: %d folds, %d scored", nrow(ann), sum(!is.na(d$score))))

### ---- Step-0 alpha background (reference ruler) -----------------------------

s0_model <- read.csv(file.path(STEP0_DIR, "model_alpha.csv"), stringsAsFactors = FALSE)
s0_out   <- read.csv(file.path(STEP0_DIR, "output_alpha.csv"), stringsAsFactors = FALSE)
s0 <- merge(s0_model, s0_out[, c("ID", SCORE_COL)], by.x = "id", by.y = "ID")
s0$score <- s0[[SCORE_COL]]
s0$cdr3_len <- nchar(s0$cdr3_TRA)

pct <- function(x, ref) 100 * mean(ref <= x, na.rm = TRUE)
d$step0_pct <- vapply(d$score, pct, numeric(1), ref = s0$score)

message(sprintf("step-0 alpha background: n=%d, median %.3f",
                nrow(s0), median(s0$score, na.rm = TRUE)))

### ---- Per-length comparison -------------------------------------------------

message("\n=== TRAJ31 vs other J, within CDR3 length ===")
rows <- list()
for (L in sort(unique(d$cdr3_len))) {
  a <- d$score[d$arm == "TRAJ31" & d$cdr3_len == L]
  b <- d$score[d$arm == "otherJ" & d$cdr3_len == L]
  w <- suppressWarnings(wilcox.test(a, b))
  rows[[length(rows) + 1L]] <- data.frame(
    L          = L,
    n_TRAJ31   = length(a),
    n_otherJ   = length(b),
    med_TRAJ31 = round(median(a), 3),
    med_otherJ = round(median(b), 3),
    delta      = round(median(a) - median(b), 3),
    max_TRAJ31 = round(max(a), 3),
    max_otherJ = round(max(b), 3),
    # P(a random TRAJ31 fold beats a random otherJ fold at this length)
    auc        = round(mean(outer(a, b, ">") + 0.5 * outer(a, b, "==")), 3),
    p          = signif(w$p.value, 2))
}
per_len <- do.call(rbind, rows)
print(per_len, row.names = FALSE)

### ---- Pooled, stratified by length ------------------------------------------
# Stratified so the length effect cannot leak into the J comparison.

message("\n=== pooled over lengths (length-stratified) ===")
num <- 0; den <- 0
for (L in unique(d$cdr3_len)) {
  a <- d$score[d$arm == "TRAJ31" & d$cdr3_len == L]
  b <- d$score[d$arm == "otherJ" & d$cdr3_len == L]
  num <- num + sum(outer(a, b, ">")) + 0.5 * sum(outer(a, b, "=="))
  den <- den + length(a) * length(b)
}
message(sprintf("stratified AUC (TRAJ31 > otherJ): %.3f   [0.5 = no effect]", num / den))

# Rank test on length-centred scores
d$score_c <- d$score - ave(d$score, d$cdr3_len, FUN = function(x) median(x, na.rm = TRUE))
wp <- suppressWarnings(wilcox.test(score_c ~ arm, data = d))
message(sprintf("Wilcoxon on length-centred scores: p = %.3g", wp$p.value))
message(sprintf("median TRAJ31 %.3f  vs  otherJ %.3f  (all lengths pooled)",
                median(d$score[d$arm == "TRAJ31"]),
                median(d$score[d$arm == "otherJ"])))

### ---- Where do the arms sit on the step-0 ruler -----------------------------

message("\n=== step-0 percentile by arm and length ===")
print(round(tapply(d$step0_pct, list(d$arm, d$cdr3_len), median), 1))

### ---- Did we reproduce the 0.818 fold --------------------------------------

REF_CDR3  <- "CATDRNNNARLMF"   # the step-0 TRAV17/TRAJ31 fold that scored 0.818
REF_SCORE <- s0$score[s0$TRAV == "TRAV17" & s0$cdr3_TRA == REF_CDR3]
if (length(REF_SCORE) == 1) {
  hit <- d[d$cdr3_TRA == REF_CDR3, ]
  message(sprintf("\n%s: step-0 %.3f, regenerated here %s",
                  REF_CDR3, REF_SCORE,
                  if (nrow(hit)) sprintf("%.3f", hit$score[1]) else "not in panel"))
  message(sprintf("TRAJ31 folds at or above %.3f: %d of %d",
                  REF_SCORE, sum(d$score[d$arm == "TRAJ31"] >= REF_SCORE),
                  sum(d$arm == "TRAJ31")))
  message(sprintf("otherJ folds at or above %.3f: %d of %d",
                  REF_SCORE, sum(d$score[d$arm == "otherJ"] >= REF_SCORE),
                  sum(d$arm == "otherJ")))
}

### ---- Top folds -------------------------------------------------------------

message("\n=== top 15 folds ===")
top <- d[order(-d$score), c("ID", "arm", "TRAJ", "cdr3_TRA", "cdr3_len", "score", "step0_pct")]
top$score <- round(top$score, 3); top$step0_pct <- round(top$step0_pct, 1)
print(head(top, 15), row.names = FALSE)

### ---- Which J genes come out on top in the control arm ---------------------

message("\n=== control arm, by J (median score) ===")
ctl <- d[d$arm == "otherJ", ]
agg <- aggregate(score ~ TRAJ, ctl, function(x) c(n = length(x), med = median(x)))
agg <- data.frame(TRAJ = agg$TRAJ, n = agg$score[, "n"], med = round(agg$score[, "med"], 3))
print(head(agg[order(-agg$med), ], 10), row.names = FALSE)

write.csv(d[order(-d$score), ], file.path(TEST_DIR, "traj31_test_scored.csv"), row.names = FALSE)
message(sprintf("\nwrote %s", file.path(TEST_DIR, "traj31_test_scored.csv")))
